#include <cassert>
#include <iostream>
#include <set>
#include <vector>
using namespace std;

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);

  int H, W, Q;
  cin >> H >> W >> Q;

  vector<set<int>> g1(H), g2(W);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      g1[i].insert(j);
      g2[j].insert(i);
    }
  }

  auto erase = [&](int i, int j) { g1[i].erase(j), g2[j].erase(i); };

  while (Q--) {
    int R, C;
    cin >> R >> C;
    --R, --C;

    if (g1[R].count(C)) {
      erase(R, C);
      continue;
    }

    // 上
    {
      auto it = g2[C].lower_bound(R);
      if (it != begin(g2[C])) erase(*prev(it), C);
    }
    // 下
    {
      auto it = g2[C].lower_bound(R);
      if (it != end(g2[C])) erase(*it, C);
    }
    // 左
    {
      auto it = g1[R].lower_bound(C);
      if (it != begin(g1[R])) erase(R, *prev(it));
    }
    // 右
    {
      auto it = g1[R].lower_bound(C);
      if (it != end(g1[R])) erase(R, *it);
    }
  }

  int ans = 0;
  for (int i = 0; i < H; i++) ans += g1[i].size();
  cout << ans << "\n";
}

class UnionFind:
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * n
        self.L = list(range(n))
        self.R = list(range(n))

    def find(self, x):
        if self.parents[x] < 0:
            return x
        else:
            self.parents[x] = self.find(self.parents[x])
            return self.parents[x]

    def merge(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y:
            return

        if self.parents[x] > self.parents[y]:
            x, y = y, x

        self.parents[x] += self.parents[y]
        self.L[x] = min(self.L[x], self.L[y])
        self.R[x] = max(self.R[x], self.R[y])
        self.parents[y] = x

    def get_LR(self, x):
        x = self.find(x)
        return (self.L[x], self.R[x])


H, W, Q = map(int, input().split())
uf_row = [UnionFind(W + 2) for i in range(H + 2)]
uf_col = [UnionFind(H + 2) for i in range(W + 2)]
erased = [[0] * (W + 2) for i in range(H + 2)]

ans = H * W


def erase(x, y):
    global ans
    if 1 <= x <= H and 1 <= y <= W:
        ans -= 1
        erased[x][y] = 1
        if erased[x][y - 1]:
            uf_row[x].merge(y - 1, y)
        if erased[x][y + 1]:
            uf_row[x].merge(y, y + 1)
        if erased[x - 1][y]:
            uf_col[y].merge(x - 1, x)
        if erased[x + 1][y]:
            uf_col[y].merge(x, x + 1)


ans = H * W
for _ in range(Q):
    x, y = map(int, input().split())
    if erased[x][y] == 0:
        erase(x, y)
        continue
    Lx, Rx = uf_col[y].get_LR(x)
    Ly, Ry = uf_row[x].get_LR(y)
    erase(Lx - 1, y)
    erase(Rx + 1, y)
    erase(x, Ly - 1)
    erase(x, Ry + 1)

print(ans)

