H, W, Q = map(int, input().split())
uf_row = UnionFind(4 * Q)
uf_col = UnionFind(4 * Q)

idx = 0
d = {}


def erase(x, y):
    global idx
    if 1 <= x <= H and 1 <= y <= W:
        d[(x, y)] = idx
        uf_row.L[idx] = y
        uf_row.R[idx] = y
        uf_col.L[idx] = x
        uf_col.R[idx] = x
        if (x, y - 1) in d:
            uf_row.merge(idx, d[(x, y - 1)])
        if (x, y + 1) in d:
            uf_row.merge(idx, d[(x, y + 1)])
        if (x - 1, y) in d:
            uf_col.merge(idx, d[(x - 1, y)])
        if (x + 1, y) in d:
            uf_col.merge(idx, d[(x + 1, y)])
        idx += 1


for _ in range(Q):
    x, y = map(int, input().split())
    if (x, y) not in d:
        erase(x, y)
        continue
    i = d[(x, y)]
    Lx, Rx = uf_col.get_LR(i)
    Ly, Ry = uf_row.get_LR(i)
    erase(Lx - 1, y)
    erase(Rx + 1, y)
    erase(x, Ly - 1)
    erase(x, Ry + 1)

print(H * W - idx)
